// ---------------------------------------------------------------------------
// lookupExtFnSummary — binary search by lowercase function name.
// Returns nullptr if the function is not in the table.
// ---------------------------------------------------------------------------
inline const ExtFnSummary *lookupExtFnSummary(std::string_view lowerName) noexcept
{
    auto it = std::lower_bound(
        kExtFnSummary.begin(), kExtFnSummary.end(), lowerName,
        [](const ExtFnSummary &e, std::string_view n) { return e.name < n; });
    if (it != kExtFnSummary.end() && it->name == lowerName)
        return &*it;
    return nullptr;
}

